/bin/bash -lc "python - << 'PY'
import numpy as np
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.svm import SVC
from sklearn.ensemble import RandomForestClassifier, ExtraTreesClassifier
from sklearn.discriminant_analysis import LinearDiscriminantAnalysis
from sklearn.metrics import accuracy_score

tr=np.load('/app/data/train.npz',allow_pickle=False)
va=np.load('/app/data/val.npz',allow_pickle=False)
Xtr,ytr=tr['X'],tr['y']
Xva,yva=va['X'],va['y']

def feats(X,mode):
    if mode=='flat':
        return X.reshape(len(X),-1)
    if mode=='sum_t':
        return X.sum(axis=2)
    if mode=='sum_u':
        return X.sum(axis=1)
    if mode=='mean_t':
        return X.mean(axis=2)
    if mode=='pair':
        a=X.reshape(len(X),-1)
        b=X.sum(axis=2)
        c=X.sum(axis=1)
        return np.concatenate([a,b,c],axis=1)
    raise ValueError

modes=['flat','sum_t','sum_u','mean_t','pair']
models={
'logreg': lambda: make_pipeline(StandardScaler(),LogisticRegression(max_iter=5000,multi_class='multinomial',C=1.0)),
'logreg_l2c3': lambda: make_pipeline(StandardScaler(),LogisticRegression(max_iter=5000,multi_class='multinomial',C=3.0)),
'svc_rbf': lambda: make_pipeline(StandardScaler(),SVC(C=3,gamma='scale')),
'svc_lin': lambda: make_pipeline(StandardScaler(),SVC(C=1,kernel='linear')),
'lda': lambda: make_pipeline(StandardScaler(),LinearDiscriminantAnalysis()),
'rf': lambda: RandomForestClassifier(n_estimators=500,random_state=0),
'et': lambda: ExtraTreesClassifier(n_estimators=800,random_state=0),
}

best=None
for mode in modes:
    ftr,fva=feats(Xtr,mode),feats(Xva,mode)
    for name,ctor in models.items():
        clf=ctor(); clf.fit(ftr,ytr)
        p=clf.predict(fva)
        acc=accuracy_score(yva,p)
        print(f'{mode:6s} {name:10s} {acc:.4f}')
        if best is None or acc>best[0]:
            best=(acc,mode,name,clf)
print('BEST',best[0],best[1],best[2])

# also check consistency y vs image_id mapping
ids=tr['image_id']
map_emp={}
ok=True
for yi,iid in zip(ytr,ids):
    if yi in map_emp and map_emp[yi]"'!=iid: ok=False
    map_emp[yi]=iid
print('"'mapping train',map_emp,'consistent',ok)
idsv=va['image_id']
ok2=True
for yi,iid in zip(yva,idsv):
    if yi in map_emp and map_emp[yi]"'!=iid: ok2=False
print('"'mapping val consistent w train',ok2)
PY"

